// Generated by Cypress Author — 2026-05-25
import { defaultDbSeed, DBSeed, getSpriteFromCels } from '../support/data';
import { rgba } from '../support/utils';

const T = rgba(0, 0, 0, 0);
const RED = rgba(255, 0, 0);
const GREEN = rgba(0, 128, 0);
const BLACK = rgba(0, 0, 0);

const twoFramesTwoLayersSeed: DBSeed = {
  ...defaultDbSeed,
  sprite: getSpriteFromCels(
    [
      [[[RED, T], [T, T]], [[T, T], [T, T]]],   // frame-0: layer-0 red(0,0) | layer-1 empty
      [[[T, T], [T, GREEN]], [[GREEN, T], [T, T]]], // frame-1: layer-0 green(1,1) | layer-1 empty
    ],
    [{ duration: 100 }, { duration: 100 }],
    [
      { 'visible?': true, 'automatic-linking?': false, name: 'Layer 1' },
      { 'visible?': true, 'automatic-linking?': false, name: 'Layer 2' }
    ]
  )
};

describe('Timeline', () => {
  describe('Display', () => {
    it.only('frame numbers, layer names, cel previews, and canvas match selected cel', () => {
      cy.startApp(twoFramesTwoLayersSeed);

      cy.assertTimelineLabels(2, ['Layer 1', 'Layer 2']);

      cy.assertTimelineCels([
        [[[RED, T], [T, T]], [[T, T], [T, T]]],
        [[[T, T], [T, GREEN]], [[GREEN, T], [T, T]]],
      ], { activeFrameIdx: 0, activeLayerIdx: 0 });

      cy.assertVisibleCanvasPixels([[RED, T], [T, T]], 'canvas shows frame-0 layer-0: red pixel');

      cy.get('[data-testid="cel-1-1"]').click();

      cy.assertTimelineCels([
        [[[RED, T], [T, T]], [[T, T], [T, T]]],
        [[[T, T], [T, GREEN]], [[GREEN, T], [T, T]]],
      ], { activeFrameIdx: 1, activeLayerIdx: 1 });

      cy.assertVisibleCanvasPixels([[GREEN, T], [T, GREEN]], 'canvas shows frame-1 layer-0: green pixel');
    });
  });

  describe('Frames', () => {
    it('add empty frame → new frame is active, is empty, draw works', () => {
      cy.startApp(twoFramesTwoLayersSeed);

      cy.get('[data-testid^="frame-"]').should('have.length', 2);

      cy.get('[title="add empty frame"]').click();

      cy.assertTimelineLabels(3, ['Layer 1', 'Layer 2']);
      cy.assertTimelineCels([
        [[[RED, T], [T, T]], [[T, T], [T, T]]],   // frame-0: layer-0 red | layer-1 empty
        [[[T, T], [T, T]], [[T, T], [T, T]]],     // frame-1 (new, active): empty | empty
        [[[T, T], [T, GREEN]], [[GREEN, T], [T, T]]], // frame-2 (was frame-1): layer-0 green | layer-1 empty
      ], { activeFrameIdx: 1, activeLayerIdx: 0 });

      cy.assertVisibleCanvasPixels([[T, T], [T, T]], 'new frame canvas is transparent');

      cy.selectTool('pen');
      cy.drawAtCanvasPixel(0, 0);
      cy.assertVisibleCanvasPixels([[BLACK, T], [T, T]], 'pixel drawn on new frame');
      cy.assertTimelineCels([
        [[[RED, T], [T, T]], [[T, T], [T, T]]],   // frame-0: layer-0 red | layer-1 empty
        [[[BLACK, T], [T, T]], [[T, T], [T, T]]],     // frame-1 (new, active): empty | empty
        [[[T, T], [T, GREEN]], [[GREEN, T], [T, T]]], // frame-2 (was frame-1): layer-0 green | layer-1 empty
      ], { activeFrameIdx: 1, activeLayerIdx: 0 });
    });
  });
});
